import{_ as e,c as a,o as d,ag as i}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Repeating tasks and reusable evidence","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/repeat-map.md","filePath":"practice/aws/repeat-map.md"}'),r={name:"practice/aws/repeat-map.md"};function n(s,t,o,l,c,p){return d(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="repeating-tasks-and-reusable-evidence" tabindex="-1">Repeating tasks and reusable evidence <a class="header-anchor" href="#repeating-tasks-and-reusable-evidence" aria-label="Permalink to “Repeating tasks and reusable evidence”">​</a></h1><p>Repeating means another required application of a topic, not an exemption. Resource reuse is encouraged when compatible. Never reuse a stale URL or removed stack as if it still demonstrated working behavior.</p><table tabindex="0"><thead><tr><th>Capability</th><th>First practice</th><th>Required repetition</th><th>What must be new</th></tr></thead><tbody><tr><td>Account, MFA, CLI, alerts</td><td>P01</td><td>A01</td><td>Recheck state; add exact budget thresholds</td></tr><tr><td>Permissions</td><td>P01/P03–P08</td><td>A02, A04, A11</td><td>Compare identities, denied actions and deployment/service roles</td></tr><tr><td>Static files</td><td>P02</td><td>A03, A04</td><td>EC2 server vs S3 website behavior</td></tr><tr><td>Private CDN hosting</td><td>P02</td><td>A05, A06, A11</td><td>Manual/CLI configuration, alternate origins, templates and pipeline</td></tr><tr><td>Resource creation</td><td>Practitioner CDK</td><td>Associate console, CLI and CloudFormation</td><td>Repeatability and interface differences</td></tr><tr><td>Product APIs</td><td>P03/P04</td><td>A03, A10, A11</td><td>EC2 vs Lambda; HTTP vs REST API; SAM delivery</td></tr><tr><td>DynamoDB</td><td>P04</td><td>A08, A09</td><td>Global tables, SDK CRUD and stream-triggered notification</td></tr><tr><td>S3 upload/events</td><td>P05</td><td>A04, A10</td><td>SDK/presign boundaries and minimal trigger observations</td></tr><tr><td>Messaging</td><td>P06</td><td>A09</td><td>Orders flow, stream transition and deliberate DLQ failure</td></tr><tr><td>RDS</td><td>P08</td><td>A08</td><td>Bastion/client access, EC2 backend and proxy comparison</td></tr><tr><td>VPC/EC2</td><td>P08/A03</td><td>A06/A07/A08</td><td>Explicit network matrix, IaC rebuild and database integration</td></tr><tr><td>Deployment</td><td>P02/P03</td><td>A05/A06/A11</td><td>CLI updates, change sets, quality gates and pipeline dependencies</td></tr><tr><td>Serverless API scaffolding</td><td>P03/A10</td><td>A12</td><td>AI service behavior and evidence of reviewing generated code</td></tr></tbody></table><h2 id="repetition-within-one-module" tabindex="-1"><span class="hub-section-number">1 </span>Repetition within one module <a class="header-anchor" href="#repetition-within-one-module" aria-label="Permalink to “1 Repetition within one module”">​</a></h2><ul><li>A02 repeats console identity management through CLI.</li><li>A03 repeats instance creation through CLI, tests an AMI through replacement and compares ALB behavior with/without stickiness.</li><li>A04 repeats object operations through console, CLI, SDK and different IAM identities.</li><li>A05 repeats distribution management through CLI and compares cache configurations.</li><li>A06 repeats earlier resources through CloudFormation, then CDK; the nested stack and diagram remain required.</li><li>A07 repeats the manual network through CloudFormation.</li><li>A08 repeats persistence operations through console, CLI, SDK, application and IaC; PostgreSQL driver operations differ from RDS management APIs.</li><li>A10 repeats product behavior through HTTP API and REST API.</li><li>A11 repeats deployment manually and through the pipeline, then tunes its CLI definition.</li></ul><p>Each record should state the prior artifact reused, the change made and the additional result observed. Original optional actions remain identifiable on the module pages, but are required under this learning path.</p>',6)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
